  const data=await response.json(),raw=(data.candidates?.[0]?.content?.parts||[]).filter(x=>!x.thought&&x.text).map(x=>x.text).join('');let answer;try{answer=JSON.parse(raw)}catch{throw new Error('A IA retornou uma resposta inválida.')}if(!answer.reply?.trim())throw new Error('A IA não retornou texto.');const reply=String(answer.reply).trim().slice(0,4000);
