function resolveSpintax(text){for(let i=0;i<20&&/\{[^{}]*\|[^{}]*\}/.test(text);i++)text=text.replace(/\{([^{}]*\|[^{}]*)\}/g,(_,choices)=>{const parts=choices.split('|');return parts[Math.floor(Math.random()*parts.length)]});return text}
async function generateQueueMessage(env,url,config,company,current){const response=await workerApi.fetch(new Request(url.origin+'/api/generate-message',{method:'POST',headers:{Origin:url.origin,'Content-Type':'application/json'},body:JSON.stringify({company,niche:'Comércio local',goal:'Reescrever o texto atual',tone:config.tone,length:config.length,emojis:config.emojis,details:config.offer,current})}),env);const data=await response.json();if(!response.ok)throw new Error(data.error||'Falha ao preparar mensagem com IA.');return data.message}
async function queueTiming(env){const instances=(await statement(env,"SELECT * FROM instances WHERE status='CONNECTED' ORDER BY updated_at,name").all()).results||[];const processing=await statement(env,"SELECT id FROM send_queue WHERE status='PROCESSING' LIMIT 1").first();const ready=instances.find(i=>!i.rest_until||Date.parse(i.rest_until)<=Date.now());return {processing:!!processing,nextSendAt:ready?new Date().toISOString():instances.map(i=>i.rest_until).sort()[0]||null}}
async function processQueue(env){
 const rules=await statement(env,'SELECT * FROM send_rules WHERE id=1').first();if(rules?.queue_state!=='RUNNING')return {state:rules?.queue_state||'PAUSED'};
 if(await statement(env,"SELECT id FROM send_queue WHERE status='PROCESSING' LIMIT 1").first())return {processing:true};
 const row=await statement(env,"SELECT q.*,c.company,c.phone FROM send_queue q JOIN contacts c ON c.id=q.contact_id WHERE q.status='QUEUED' ORDER BY q.position LIMIT 1").first();
 if(!row){await statement(env,"UPDATE send_rules SET queue_state='STOPPED' WHERE id=1").run();return {state:'STOPPED',message:'Fila concluída.'}}
 const instances=(await statement(env,"SELECT * FROM instances WHERE status='CONNECTED' ORDER BY updated_at,name").all()).results||[];
 const instance=instances.find(i=>!i.rest_until||Date.parse(i.rest_until)<=Date.now());if(!instance)return {state:'RUNNING',...await queueTiming(env)};
 let prepared;try{prepared=JSON.parse(row.message)}catch{}if(!prepared?.text?.trim())return {error:'Prepare as mensagens antes de iniciar.'};
 const claim=await statement(env,"UPDATE send_queue SET status='PROCESSING',processing_at=?,instance_name=? WHERE id=? AND status='QUEUED' AND NOT EXISTS(SELECT 1 FROM send_queue WHERE status='PROCESSING') AND EXISTS(SELECT 1 FROM send_rules WHERE id=1 AND queue_state='RUNNING')",new Date().toISOString(),instance.name,row.id).run();if(!claim.meta?.changes)return {processing:true};
 let accepted=false;
 try{
  const go=instance.provider==='EVOLUTION_GO',key=await decryptSecret(go?instance.instance_token_cipher:instance.token_cipher,env);
  let response=await fetch(instance.api_url.replace(/\/$/,'')+(go?'/send/text':'/message/sendText/'+encodeURIComponent(instance.name)),{method:'POST',headers:{'Content-Type':'application/json',apikey:key},body:JSON.stringify({number:row.phone,text:prepared.text}),signal:AbortSignal.timeout(30000)});
  if(go&&response.status===404)response=await fetch(instance.api_url.replace(/\/$/,'')+'/message/sendText',{method:'POST',headers:{'Content-Type':'application/json',apikey:key},body:JSON.stringify({number:row.phone,text:prepared.text}),signal:AbortSignal.timeout(30000)});
  let result={};try{result=await response.json()}catch{}
  if(!response.ok||result.error||result.success===false)throw new Error('A integração recusou o envio (HTTP '+response.status+').');accepted=true;
  const now=new Date().toISOString();
  // Persist the exact accepted text before removing the contact from the active lists.
  await statement(env,'INSERT OR IGNORE INTO sends(id,company,phone,message,type,opened_at,status,confirmed_at) VALUES(?,?,?,?,?,?,?,?)',row.id,row.company,row.phone,prepared.text,prepared.type,now,'sent',now).run();
  await statement(env,"UPDATE contacts SET status=CASE WHEN interested=1 THEN 'INTERESTED' ELSE 'SENT' END,last_sent_at=?,last_instance=? WHERE id=?",now,instance.name,row.contact_id).run();
  await statement(env,"UPDATE send_queue SET status='SENT',sent_at=?,error=NULL WHERE id=?",now,row.id).run();
  const count=(instance.rest_until&&Date.parse(instance.rest_until)<=Date.now()&&instance.sent_in_cycle>=instance.messages_per_cycle?0:instance.sent_in_cycle)+1;
  const min=Number(instance.min_seconds),max=Math.max(min,Number(instance.max_seconds));const delay=count>=instance.messages_per_cycle?Number(instance.rest_minutes)*60:min+Math.floor(Math.random()*(max-min+1));
  await statement(env,'UPDATE instances SET sent_in_cycle=?,rest_until=?,updated_at=? WHERE id=?',count,new Date(Date.now()+delay*1000).toISOString(),now,instance.id).run();
  await event(env,row.contact_id,'SENT',JSON.stringify({queueId:row.id,instance:instance.name,message:prepared.text}));return {sent:true,...await queueTiming(env)};
 }catch(error){
  const message=accepted?'Envio aceito, mas o registro falhou. Confira o histórico antes de repetir.':error.name==='TimeoutError'?'Tempo de resposta esgotado. Confira o WhatsApp antes de repetir.':error.message;
  await statement(env,"UPDATE send_queue SET status='ERROR',error=? WHERE id=?",message,row.id).run();
  await statement(env,"UPDATE send_rules SET queue_state='PAUSED' WHERE id=1").run();return {state:'PAUSED',error:message};
 }
}

async function instanceList(env){return (await statement(env,"SELECT id,name,status,COALESCE(provider,'EVOLUTION_API') AS provider,api_url AS apiUrl,last_checked_at AS lastCheckedAt,rest_until AS restUntil,sent_in_cycle AS sentInCycle,min_seconds AS minSeconds,max_seconds AS maxSeconds,messages_per_cycle AS messagesPerCycle,rest_minutes AS restMinutes,webhook_status AS webhookStatus FROM instances ORDER BY name").all()).results||[]}
function connectionStatus(data,go=false){const state=String(data?.instance?.state||data?.data?.state||data?.state||'').toLowerCase();if(state)return ['open','connected','online'].includes(state)?'CONNECTED':['close','closed','disconnected','offline','connecting'].includes(state)?'DISCONNECTED':'UNKNOWN';const d=data?.data||data||{};const truth=v=>v===true||v===1||v==='true';if(go&&('loggedIn' in d||'connected' in d)){const logged='loggedIn' in d?truth(d.loggedIn):truth(d.connected),connected='connected' in d?truth(d.connected):logged;return logged&&connected?'CONNECTED':'DISCONNECTED'}return 'UNKNOWN'}
function connectionEvent(payload){const event=String(payload.event||payload.type||'').toLowerCase().replace(/[_ .-]/g,'');if(event==='connected')return 'CONNECTED';if(['disconnected','loggedout'].includes(event))return 'DISCONNECTED';if(event==='connectionupdate')return connectionStatus(payload.data||payload,payload.data?.loggedIn!==undefined);return null}
async function refreshInstance(env,row,force=false){if(!force&&row.last_checked_at&&Date.now()-Date.parse(row.last_checked_at)<4500)return row.status;let status='UNKNOWN';try{const go=row.provider==='EVOLUTION_GO',key=await decryptSecret(go?row.instance_token_cipher:row.token_cipher,env);const response=await fetch(row.api_url.replace(/\/$/,'')+(go?'/instance/status':'/instance/connectionState/'+encodeURIComponent(row.name)),{headers:{apikey:key},signal:AbortSignal.timeout(4000)});if(response.ok)status=connectionStatus(await response.json(),go)}catch{}await statement(env,'UPDATE instances SET status=?,last_checked_at=? WHERE id=?',status,new Date().toISOString(),row.id).run();return status}

function normalizeApiKey(value){return String(value||'').trim().replace(/[\u200B-\u200D\uFEFF]/g,'').replace(/^(?:export\s+)?(?:GEMINI_API_KEY|GOOGLE_API_KEY|API_KEY)\s*=\s*/i,'').replace(/^Bearer\s+/i,'').replace(/[\s\u200B-\u200D\uFEFF]/g,'').replace(/^["'“”‘’`]+|["'“”‘’`;]+$/g,'')}
const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store'}});
